style.css:
@-moz-document domain("roblox.com") {
html::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url("https://i.postimg.cc/Ss15tYgs/Haker-Juanda-Imgur.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -9999;
}

/* Quitar fondos de Roblox */
html,
body,
.content,
.container-main,
.home-page-container,
.game-home-page-container {
    background: transparent !important;
}
}
